//! The reference as Markdown: a section per part of the spec, an entry per field with its type,
//! default, allowed values, limits, an example (the field's probe spec) and the targets that
//! render or refuse it.

use std::fmt::Write;

use super::{Field, example, fields};
use crate::spec::{Cell, Output, Row, Status, probes, table};

/// The page's opening: what it is, where it comes from, how to read a path.
const INTRO: &str = "# Spec reference

<!-- Generated by `isoloom docs --spec`. Edit the model's doc comments (the schema) or the coverage tables, then regenerate. -->

Every field of `isoloom.yml`, read from its JSON schema (`isoloom schema`, which editors use for
completion and hover), with what each target does with it, read from the coverage spec table
([COVERAGE.md](COVERAGE.md#from-the-specs-side)). In a path, `*` stands for a name you choose
(a network, a machine) and `[]` for each item of a list. An example is the smallest fragment that
uses the field, the one each target is asked to render; a target that refuses it says why.

New to Isoloom? Start with [Getting started](getting-started.md); each target is described in
[Targets](targets.md).
";

/// The whole page.
pub fn markdown() -> String {
    let all = fields(&isoloom_spec::schema::schema());
    let rows = table();
    let mut md = String::from(INTRO);
    let sections = sections(&all);
    md.push_str("\n## Sections\n\n");
    for (title, _) in &sections {
        let _ = writeln!(md, "- [{}](#{})", heading(title), slug(&heading(title)));
    }
    for (title, members) in &sections {
        let _ = write!(md, "\n## {}\n", heading(title));
        for f in members {
            entry(&mut md, f, &rows);
        }
    }
    md
}

/// A section's heading: the part of the spec it covers.
fn heading(section: &str) -> String {
    if section.is_empty() {
        "Top level".to_string()
    } else {
        format!("`{section}`")
    }
}

/// The fields by section, in the schema's order: a top-level field with fields of its own
/// opens a section (and a machine's `docker`, `vm` and `external` each one), the others are
/// the top level's.
fn sections(all: &[Field]) -> Vec<(String, Vec<&Field>)> {
    let mut out: Vec<(String, Vec<&Field>)> = vec![(String::new(), Vec::new())];
    for f in all {
        let key = section_of(&f.path, all);
        match out.iter_mut().find(|(k, _)| *k == key) {
            Some((_, members)) => members.push(f),
            None => out.push((key, vec![f])),
        }
    }
    out.retain(|(_, members)| !members.is_empty());
    out
}

/// The section a field belongs to.
fn section_of(path: &str, all: &[Field]) -> String {
    for part in ["docker", "vm", "external"] {
        let sub = format!("machines.*.{part}");
        if path == sub || path.starts_with(&format!("{sub}.")) {
            return sub;
        }
    }
    let top = path.split(['.', '[']).next().unwrap_or(path);
    let nested = all
        .iter()
        .any(|f| f.path.len() > top.len() && f.path.starts_with(top) && is_inside(&f.path, top));
    if nested { top.to_string() } else { String::new() }
}

/// Whether `path` is a field inside `parent`.
fn is_inside(path: &str, parent: &str) -> bool {
    path.strip_prefix(parent).is_some_and(|rest| rest.starts_with('.') || rest.starts_with('['))
}

/// One field's entry.
fn entry(md: &mut String, f: &Field, rows: &[Row]) {
    let _ = write!(md, "\n### `{}`\n\n", f.path);
    if !f.description.is_empty() {
        let _ = write!(md, "{}\n\n", f.description);
    }
    let _ = writeln!(md, "- **Type:** {}", f.kind);
    if let Some(d) = &f.default {
        let _ = writeln!(md, "- **Default:** `{d}`");
    }
    allowed(md, &f.allowed);
    if !f.limits.is_empty() {
        let _ = writeln!(md, "- **Limits:** {}", f.limits.join("; "));
    }
    if !f.members.is_empty() {
        let names: Vec<String> = f.members.iter().map(|m| format!("`{m}`")).collect();
        let _ = writeln!(md, "- **Holds:** {}, each as on a machine", names.join(", "));
    }
    for e in examples(f) {
        let _ = writeln!(md, "- **Example:** `{e}`");
    }
    targets(md, &f.path, rows);
}

/// The allowed values: inline when they need no explanation, else one per line.
fn allowed(md: &mut String, values: &[(String, String)]) {
    if values.is_empty() {
        return;
    }
    if values.iter().all(|(_, meaning)| meaning.is_empty()) {
        let list: Vec<String> = values.iter().map(|(v, _)| format!("`{v}`")).collect();
        let _ = writeln!(md, "- **Allowed:** {}", list.join(", "));
        return;
    }
    md.push_str("- **Allowed:**\n");
    for (v, meaning) in values {
        let _ = writeln!(md, "  - `{v}`: {}", meaning.replace('\n', " "));
    }
}

/// The schema's own examples, else the field's probe spec.
fn examples(f: &Field) -> Vec<String> {
    if !f.examples.is_empty() {
        return f.examples.clone();
    }
    let probe = if f.path.starts_with("cloud.") {
        probes::cloud_probe(&f.path)
    } else {
        probes::probe(&f.path)
    };
    probe.map(|p| example::focus(&p, &f.path)).into_iter().collect()
}

/// What each target does with the field: its own row, or the row of the field it is part of.
fn targets(md: &mut String, path: &str, rows: &[Row]) {
    // A list's own row is its items' (`checks[]`).
    if let Some(row) = rows
        .iter()
        .find(|r| r.path == path)
        .or_else(|| rows.iter().find(|r| r.path.strip_suffix("[]") == Some(path)))
    {
        row_lines(md, row);
        return;
    }
    let parent = rows.iter().filter(|r| is_inside(path, r.path)).max_by_key(|r| r.path.len());
    if let Some(parent) = parent {
        let _ = writeln!(md, "- **Targets:** as [`{0}`](#{1})", parent.path, slug(&format!("`{}`", parent.path)));
    }
}

/// A row's cells, grouped: rendered, partly rendered, refused (by reason), planned, unused.
fn row_lines(md: &mut String, row: &Row) {
    let pick = |keep: &dyn Fn(&Cell) -> bool| -> Vec<Output> { row.cells.iter().filter(|(_, c)| keep(c)).map(|(o, _)| *o).collect() };
    let done = pick(&|c| matches!(c, Cell::Is(Status::Done { .. })));
    let planned = pick(&|c| matches!(c, Cell::Is(Status::Planned { .. })));
    let unused = pick(&|c| matches!(c, Cell::Is(Status::NotApplicable { .. })));
    let own = row.cells.iter().find_map(|(_, c)| match c {
        Cell::Is(s @ (Status::Core { .. } | Status::Descriptive { .. })) => Some(s.note()),
        _ => None,
    });
    if let Some(note) = own {
        let _ = writeln!(md, "- **Read by Isoloom itself:** {note}");
    }
    if !done.is_empty() {
        let _ = writeln!(md, "- **Rendered by:** {}", names(&done));
    }
    for (gap, outs) in grouped(row, |c| match c {
        Cell::Is(Status::Partial { gap, .. }) => Some((*gap).to_string()),
        Cell::Is(_) | Cell::Refused(_) => None,
    }) {
        let _ = writeln!(md, "- **Partly rendered by:** {} (not yet: {gap})", names(&outs));
    }
    for (why, outs) in grouped(row, |c| match c {
        Cell::Refused(why) => Some(why.clone()),
        Cell::Is(_) => None,
    }) {
        let _ = writeln!(md, "- **Refused by:** {}: {}", names(&outs), why.replace('\n', " "));
    }
    if !planned.is_empty() {
        let _ = writeln!(md, "- **Planned for:** {}", names(&planned));
    }
    if !unused.is_empty() {
        let _ = writeln!(md, "- **Not used by:** {}", names(&unused));
    }
}

/// The outputs whose cell `key` maps to the same text, by text, in the table's order.
fn grouped(row: &Row, key: impl Fn(&Cell) -> Option<String>) -> Vec<(String, Vec<Output>)> {
    let mut out: Vec<(String, Vec<Output>)> = Vec::new();
    for (o, c) in &row.cells {
        let Some(k) = key(c) else { continue };
        match out.iter_mut().find(|(x, _)| *x == k) {
            Some((_, outs)) => outs.push(*o),
            None => out.push((k, vec![*o])),
        }
    }
    out
}

/// Outputs as a list of names, every cloud of `cloud-vm` folded into one when they all agree.
fn names(outs: &[Output]) -> String {
    let clouds: Vec<Output> = Output::all().into_iter().filter(|o| matches!(o, Output::CloudVm(_))).collect();
    let every_cloud = clouds.iter().all(|c| outs.contains(c));
    let mut list: Vec<String> = Vec::new();
    for o in outs {
        match o {
            Output::CloudVm(_) if every_cloud => {
                if !list.iter().any(|l| l.starts_with("`cloud-vm`")) {
                    list.push("`cloud-vm` (every cloud)".to_string());
                }
            }
            Output::CloudVm(cloud) => list.push(format!("`cloud-vm` ({cloud})")),
            other => list.push(format!("`{}`", other.label())),
        }
    }
    list.join(", ")
}

/// The anchor GitHub gives a heading: lower case, spaces as `-`, other punctuation dropped.
pub fn slug(heading: &str) -> String {
    heading
        .to_lowercase()
        .chars()
        .filter_map(|c| match c {
            ' ' => Some('-'),
            c if c.is_alphanumeric() || c == '-' || c == '_' => Some(c),
            _ => None,
        })
        .collect()
}
